B.aV9=s(["Quiero a mi mam\xe1.","T\xf4i y\xeau m\u1eb9."],t.s)
B.a42=s(["\xa1Hola, maestra!","Em ch\xe0o c\xf4 \u1ea1!"],t.s)
B.ajU=s(["El mar es azul.","Bi\u1ec3n xanh."],t.s)
